  const metalLists=r.reference?.metals?.lists??[],chapter=r.appliedHts.slice(0,2);
  if(metalLists.length){
    relevantFacts.add('metal_special_claim');
    if(!['72','73','74','76'].includes(chapter)){relevantFacts.add('metal_weight_verified');relevantFacts.add('no_metal_content');}
    if(metalLists.some(k=>['ii','iv','vi','vii','viii','ix','x','xi'].includes(k)))relevantFacts.add('us_metal_qualified');
    if(metalLists.some(k=>['i','ii','vi','ix'].includes(k)))relevantFacts.add('russian_aluminum_clear');
    if((origin||r.appliedOrigin)==='GB')relevantFacts.add('uk_metal_qualified');
    if(['84','85','87'].includes(chapter)&&metalLists.some(k=>['vi','vii','viii','xi'].includes(k))){relevantFacts.add('motorcycle_use');if(!r.reference?.metals?.transition)relevantFacts.add('equipment_use');}
  }
