  if(earlierMetals.length){relevantFacts.add('metal_special_claim');relevantFacts.add('content_values_verified');for(const member of earlierMetals){if(member.metal==='copper'){relevantFacts.add('copper_exceptions_clear');relevantFacts.add('copper_full_value_assessment');}if(member.described)relevantFacts.add(member.kind==='primary'?'aluminum_primary_covered':member.metal+'_derivative_covered');if(member.usException)relevantFacts.add(member.metal==='steel'?'us_steel_melt_pour':'us_aluminum_smelt_cast');if(member.metal==='aluminum'){relevantFacts.add('russian_aluminum_clear');relevantFacts.add('russian_aluminum_subject');}}}
  if(e.shipment?.cases?.length||shipmentInput.cases)for(const f of ['adcvd_scope_verified','adcvd_party_verified','adcvd_instructions_clear','adcvd_cases_complete'])relevantFacts.add(f);
